/**
 * The measured payload for the Lee Sin demo: geometry accessors and baseColorTexture images.
 *
 * PURE THREE.JS, NOTHING FETCHED. The demo builds `THREE.BufferGeometry`, `THREE.SkinnedMesh`,
 * `THREE.Skeleton` and `THREE.AnimationClip` directly. It uses no `GLTFLoader`, no `three/examples`
 * addon and no loader of any kind, and it issues no .glb, .bin, .gltf or image request while running
 * -- every byte it needs is in this module. The reference GLB is a BUILD-TIME MEASUREMENT INSTRUMENT:
 * it is not in this repository, is not served, and is never shipped to a viewer.
 *
 * WHAT IS COPIED, AND WHY IT IS SAID PLAINLY. The owner asked for a body whose triangle count and
 * triangle positions match the reference exactly. No reconstruction can deliver that: the measured
 * Surface Nets build carried 747,062 vertices and 1,495,764 triangles against the reference's 52,322
 * and 50,531 -- 14.3x and 29.6x -- so its surface could approach the reference but never coincide
 * with it, and the difference showed as thin seams that eleven separate surface fixes failed to
 * remove. So POSITION, NORMAL, TEXCOORD_0, JOINTS_0, WEIGHTS_0 and the index buffer of all 69
 * drawable nodes are transferred bit-for-bit as the accessors store them, and the 69 baseColorTexture
 * images come across in their original encoding. This is a TRANSFER, not a procedural synthesis, and
 * describing it as anything else would misrepresent the file. Elsewhere img2threejs treats the
 * reference as an instrument and copies none of this; the departure is deliberate and scoped to this
 * demo.
 *
 * WHAT IS GENERATED IN CODE. The transferred buffers are not the finished model. `weldSeamSkinning`
 * recomputes the skin binding of every vertex near a part boundary, and `capOpenBoundaries` detects
 * open boundary loops and closes them with generated fan triangles -- geometry that exists in this
 * demo and in no accessor. Vertex tangents are derived, not copied, because the reference declares
 * no TANGENT accessor.
 *
 * All 69 nodes carry an identity local transform under a single Armature, so these positions need no
 * rebasing and land in the space the rig already uses.
 *
 * Reference SHA-256 70a74553ee0c591aeffbb09bfbea92cfbc3c78d74c96a4aa2f5b7e62e224c2eb
 */

export interface SourceMeshNode {
  readonly node: number;
  readonly material: number;
  readonly vertexCount: number;
  readonly triangleCount: number;
  readonly positionsBase64: string;
  readonly normalsBase64: string;
  readonly uvsBase64: string;
  readonly jointsBase64: string;
  readonly weightsBase64: string;
  readonly indicesBase64: string;
}

export interface SourceTexture {
  readonly material: number;
  readonly mimeType: string;
  readonly bytes: number;
  readonly base64: string;
}

